<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php';Auth::requireLogin();$db=Database::getInstance()->pdo();$from=isset($_GET['from'])?$_GET['from']:date('Y-m-d');$to=isset($_GET['to'])?$_GET['to']:date('Y-m-d');$st=$db->prepare('SELECT s.*,c.name customer,u.full_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.user_id WHERE DATE(s.created_at) BETWEEN ? AND ? ORDER BY s.id DESC');$st->execute(array($from,$to));$rows=$st->fetchAll();$pageTitle='المبيعات';require APP_ROOT.'/includes/header.php';?><div class="page-heading"><div><h1>سجل المبيعات</h1><p>فواتير الفترة المحددة</p></div><a class="btn btn-coffee" href="<?= APP_URL ?>/modules/sales/pos.php">بيع جديد</a></div><form class="card card-body mb-3" method="get"><div class="row g-2 align-items-end"><div class="col-auto"><label>من</label><input class="form-control" type="date" name="from" value="<?= Helper::e($from) ?>"></div><div class="col-auto"><label>إلى</label><input class="form-control" type="date" name="to" value="<?= Helper::e($to) ?>"></div><div class="col-auto"><button class="btn btn-coffee">تصفية</button></div></div></form><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>الفاتورة</th><th>الزبون</th><th>الكاشير</th><th>التاريخ</th><th>الإجمالي</th><th>المدفوع</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= Helper::e($r['invoice_no']) ?></td><td><?= Helper::e($r['customer']?:'زبون عابر') ?></td><td><?= Helper::e($r['full_name']) ?></td><td><?= Helper::e($r['created_at']) ?></td><td><?= Helper::money($r['total']) ?></td><td><?= Helper::money($r['paid']) ?></td><td><a class="btn btn-sm btn-outline-secondary" href="<?= APP_URL ?>/modules/sales/receipt.php?id=<?= (int)$r['id'] ?>">الفاتورة</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty-state">لا توجد نتائج</td></tr><?php endif; ?></tbody></table></div></div><?php require APP_ROOT.'/includes/footer.php';
